        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The functions `um_pci_init` and `um_pci_exit` were declared as non-static, making them accessible outside their defining file. This could lead to potential naming conflicts or unintended usage in other parts of the codebase, which is not necessary since they are only intended for use within the `virt-pci.c` file. Making them static resolves this issue by limiting their scope.

        Commit message:
        um: make PCI emulation driver init/exit static

The functions aren't used elsewhere, so they can be static.

Reported-by: kernel test robot <lkp@intel.com>
Fixes: 68f5d3f3b654 ("um: add PCI over virtio emulation driver")
Signed-off-by: Johannes Berg <johannes.berg@intel.com>
Acked-By: Anton Ivanov <anton.ivanov@cambridgegreys.com>
Signed-off-by: Richard Weinberger <richard@nod.at>  

        Patch:

-int um_pci_init(void)
+static int um_pci_init(void)
 {
 	int err, i;

 	WARN_ON(logic_iomem_add_region(&virt_cfgspace_resource,
 				       &um_pci_cfgspace_ops));
 	WARN_ON(logic_iomem_add_region(&virt_iomem_resource,
 				       &um_pci_iomem_ops));

 	if (WARN(CONFIG_UML_PCI_OVER_VIRTIO_DEVICE_ID < 0,
 		 "No virtio device ID configured for PCI - no PCI support\n"))
 		return 0;

 	bridge = pci_alloc_host_bridge(0);
 	if (!bridge)
 		return -ENOMEM;

 	um_pci_fwnode = irq_domain_alloc_named_fwnode("um-pci");
 	if (!um_pci_fwnode) {
 		err = -ENOMEM;
 		goto free;
 	}

 	um_pci_inner_domain = __irq_domain_add(um_pci_fwnode, MAX_MSI_VECTORS,
 					       MAX_MSI_VECTORS, 0,
 					       &um_pci_inner_domain_ops, NULL);
 	if (!um_pci_inner_domain) {
 		err = -ENOMEM;
 		goto free;
 	}

 	um_pci_msi_domain = pci_msi_create_irq_domain(um_pci_fwnode,
 						      &um_pci_msi_domain_info,
 						      um_pci_inner_domain);
 	if (!um_pci_msi_domain) {
 		err = -ENOMEM;
 		goto free;
 	}

 	pci_add_resource(&bridge->windows, &virt_iomem_resource);
 	pci_add_resource(&bridge->windows, &busn_resource);
 	bridge->ops = &um_pci_ops;
 	bridge->map_irq = um_pci_map_irq;

 	for (i = 0; i < MAX_DEVICES; i++) {
 		resource_size_t start;

 		start = virt_cfgspace_resource.start + i * CFG_SPACE_SIZE;
 		um_pci_devices[i].iomem = ioremap(start, CFG_SPACE_SIZE);
 		if (WARN(!um_pci_devices[i].iomem, "failed to map %d\n", i)) {
 			err = -ENOMEM;
 			goto free;
 		}
 	}

 	err = pci_host_probe(bridge);
 	if (err)
 		goto free;

 	err = register_virtio_driver(&um_pci_virtio_driver);
 	if (err)
 		goto free;
 	return 0;
 free:
 	if (um_pci_inner_domain)
 		irq_domain_remove(um_pci_inner_domain);
 	if (um_pci_fwnode)
 		irq_domain_free_fwnode(um_pci_fwnode);
 	pci_free_resource_list(&bridge->windows);
 	pci_free_host_bridge(bridge);
 	return err;
 }
 module_init(um_pci_init);

-void um_pci_exit(void)
+static void um_pci_exit(void)
 {
 	unregister_virtio_driver(&um_pci_virtio_driver);
 	irq_domain_remove(um_pci_msi_domain);
 	irq_domain_remove(um_pci_inner_domain);
 	pci_free_resource_list(&bridge->windows);
 	pci_free_host_bridge(bridge);
 }
 module_exit(um_pci_exit);


